with with_prev as (select *, lag(reading_ts) over (partition by device_code order by reading_ts, id) as prev_reading_ts from device_readings), flagged as (select *, case when prev_reading_ts is null or reading_ts > prev_reading_ts + interval '20' minute then 1 else 0 end as is_new_session from with_prev), islands as (select *, sum(is_new_session) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as burst_id from flagged) select case when status_bits >= 10 then 'PREMIUM' else 'STANDARD' end as status_bits_tier, sort_array(collect_set(device_code)) as device_code_list, sum(status_bits) filter (where device_code = 'DV-04') as dv_04_total_status_bits, size(collect_set(device_code)) as num_device_codes, approx_percentile(pressure, 0.95) as pressure_p95 from islands group by 1 order by pressure_p95;
